void UGenerationSubsystem::OnPlayerDeath(AActor* DiedPawn, USacrificeLogComponent* SacrificeLog, UStarMemorialComponent* StarMemorial)
{
	if (!SacrificeLog || !StarMemorial)
	{
		UE_LOG(LogTemp, Warning, TEXT("GenerationSubsystem: Missing SacrificeLog or StarMemorial component on death"));
		return;
	}

	// Write the star from the sacrifice log into the memorial
	WriteStarFromSacrificeLog(SacrificeLog, StarMemorial);

	// Invoke the costless life ending diagnostic
	if (CostlessLifeDiagnosticActor)
	{
		InvokeCostlessLifeEndingDiagnostic(CostlessLifeDiagnosticActor, SacrificeLog);
	}

	// Show wordless will screen
	ShowWordlessWillScreen();

	// Respawn the heir at the habitat with halved credits
	if (DiedPawn && DiedPawn->GetWorld())
	{
		APlayerController* PlayerController = UGameplayStatics::GetPlayerController(DiedPawn->GetWorld(), 0);
		if (PlayerController)
		{
			RespawnHeirAtHabitatWithHalvedCredits(PlayerController);
		}
	}
}

